2	//   "I call these jobs, not projects. Please use that word everywhere."
3	//
4	// The concept the app calls a "project" is renamed in the UI to a "job": every user-visible place
5	// that reads "Project"/"Projects"/"project"/"projects" must now read "Job"/"Jobs"/"job"/"jobs".
6	// This is a wording change only — the data-testid anchors are an immutable public API and keep
7	// their existing `project-*` / `nav-projects` names (they are not user-visible), and the seeded data
8	// (client names, job names) is unchanged. So the existing specs, which assert through those testids
9	// and through seeded values, keep passing unchanged; what changes is the static labels, headings,
10	// button text, column headers, empty states and placeholders the app renders around them.
11	//
12	// Asserts ONLY through the UI (data-testid). Each assertion scopes to an anchored element and checks
13	// that it now carries the new word and no longer carries the old one. The old word is matched with a
14	// case-insensitive regex (/project/i) so BOTH "Project" (headings/labels) and "project" (button /
15	// empty-state copy) are caught; the new word likewise (/job/i, or /jobs/i where the plural is used).
16	// Seeded names are chosen so none contains the string "project" or "job" — a negative assertion
17	// cannot be defeated, nor a positive one satisfied, by accident through the data.
18	//
19	// These SHOULD FAIL before the change: the app says "project(s)" in all these places today.
20	import { test, expect } from '@playwright/test';
21	import { resetAndSeed } from '../support/seed';
22	
23	const CLIENTS = [
24	  { id: 1, name: 'Acme Corp', email: 'ops@acme.example' },
25	  { id: 2, name: 'Globex', email: 'hello@globex.example' },
26	];
27	const JOBS = [
28	  { id: 1, clientId: 1, name: 'Website redesign' },
29	  { id: 2, clientId: 2, name: 'Warehouse automation' },
30	];
31	
32	test.describe('jobs terminology (renamed from projects)', () => {
33	  test('the nav link reads "Jobs"', async ({ page }) => {
34	    await resetAndSeed({ clients: [], projects: [] });
35	
36	    await page.goto('/');
37	    await expect(page.getByTestId('app-root')).toBeVisible();
38	
39	    // The nav entry keeps its stable testid (nav-projects) but its visible label is now "Jobs".
40	    await expect(page.getByTestId('nav-projects')).toHaveText('Jobs');
41	  });
42	
43	  test('the jobs list page heading and add button say "job(s)", not "project(s)"', async ({ page }) => {
44	    await resetAndSeed({ clients: CLIENTS, projects: JOBS });
45	
46	    await page.goto('/projects');
47	
48	    const listPage = page.getByTestId('projects-page');
49	    await expect(listPage).toBeVisible();
50	    // The heading (and everything else on the page) now uses the new word; nothing reads "project".
51	    await expect(listPage).toContainText(/jobs/i);
52	    await expect(listPage).not.toContainText(/project/i);
53	
54	    // "Add project" -> "Add job".
55	    const submit = page.getByTestId('project-form-submit');
56	    await expect(submit).toContainText(/job/i);
57	    await expect(submit).not.toContainText(/project/i);
58	  });
59	
