61	    // A client exists so the list is empty of JOBS specifically, not of all data.
62	    await resetAndSeed({ clients: [CLIENTS[0]], projects: [] });
63	
64	    await page.goto('/projects');
65	
66	    const empty = page.getByTestId('projects-empty');
67	    await expect(empty).toBeVisible();
68	    await expect(empty).toContainText(/jobs/i);
69	    await expect(empty).not.toContainText(/project/i);
70	  });
71	
