74	
75	    await page.goto('/projects');
76	    await page.getByTestId('project-open-1').click();
77	
78	    const detail = page.getByTestId('project-detail-page');
79	    await expect(detail).toBeVisible();
80	    await expect(detail).toContainText(/job/i);
81	    await expect(detail).not.toContainText(/project/i);
82	  });
83	
