130	    await resetAndSeed({ clients: CLIENTS, projects: JOBS });
131	
132	    await page.goto('/');
133	
134	    // Placeholder "Search clients and projects" -> "... and jobs". (A placeholder is an attribute,
135	    // not text content, so it is asserted via the attribute.)
136	    const search = page.getByTestId('global-search');
