// read "project" (jobs terminology), and these literal codes must not accidentally satisfy that.
// This SHOULD FAIL before the change: a job carries no project-code today, the add form has no
// project-form-code control, and nothing enforces code uniqueness.
import { test, expect } from '@playwright/test';
import { resetAndSeed } from '../support/seed';

test.describe('job reference code', () => {
  test('shows each job its OWN reference code, not a shared or fixed value', async ({ page }) => {
    await resetAndSeed({
      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
      projects: [
        { id: 1, clientId: 1, name: 'Website redesign', code: 'WR-01' },
        { id: 2, clientId: 1, name: 'Warehouse automation', code: 'WH-02' },
      ],
    });

    // Job 1 shows its own code on its detail page.
    await page.goto('/projects');
    await page.getByTestId('project-open-1').click();
    await expect(page.getByTestId('project-detail-page')).toBeVisible();
    const code1 = page.getByTestId('project-detail-page').getByTestId('project-code');
    await expect(code1).toBeVisible();
    await expect(code1).toContainText('WR-01');
    await expect(code1).not.toContainText('WH-02');

    // Job 2 shows a DIFFERENT code — proving each job carries its own, not a fixed string.
    await page.goto('/projects');
    await page.getByTestId('project-open-2').click();
    await expect(page.getByTestId('project-detail-page')).toBeVisible();
    const code2 = page.getByTestId('project-detail-page').getByTestId('project-code');
    await expect(code2).toBeVisible();
    await expect(code2).toContainText('WH-02');
    await expect(code2).not.toContainText('WR-01');
  });

  test('sets the reference code entered when the job is created', async ({ page }) => {
    await resetAndSeed({
      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
      projects: [],
